SELECT order_id FROM source_orders
UNION
SELECT order_id FROM warehouse_orders;

SELECT order_id FROM source_orders
INTERSECT
SELECT order_id FROM warehouse_orders;

SELECT order_id FROM source_orders
EXCEPT
SELECT order_id FROM warehouse_orders;

SELECT order_id FROM (SELECT order_id FROM source_orders EXCEPT SELECT order_id FROM warehouse_orders)
UNION
SELECT order_id FROM (SELECT order_id FROM warehouse_orders EXCEPT SELECT order_id FROM source_orders);

SELECT 'source_only' AS direction, COUNT(*) AS n FROM (
  SELECT order_id FROM source_orders EXCEPT SELECT order_id FROM warehouse_orders
)
UNION ALL
SELECT 'warehouse_only', COUNT(*) FROM (
  SELECT order_id FROM warehouse_orders EXCEPT SELECT order_id FROM source_orders
);

SELECT order_id, amount FROM source_orders
INTERSECT
SELECT order_id, amount FROM warehouse_orders;

SELECT order_id, customer_name, amount, 'source' AS system FROM source_orders
UNION ALL
SELECT order_id, customer_name, amount, 'warehouse' AS system FROM warehouse_orders;

SELECT LOWER(TRIM(customer_name)) AS customer FROM source_orders
INTERSECT
SELECT LOWER(TRIM(customer_name)) AS customer FROM warehouse_orders;

SELECT order_id FROM (SELECT order_id FROM source_orders EXCEPT SELECT order_id FROM vendor_orders)
UNION
SELECT order_id FROM (SELECT order_id FROM vendor_orders EXCEPT SELECT order_id FROM source_orders);
